/* In Order Words · infinite grammar practice generator
   Every call builds a new item from banks of people, verbs and real-life situations.
   Item types:
   mc   {t,ctx,q,o,a,e:[en,es]}         choose in context
   tr   {t,ctx,q,s|k,a:[...],e}         rewrite (PAU transformation)
   err  {t,q,a:[...],e}                 find and fix the mistake
   text {t,frame,title,intro,outro,items:[mc...]}   real-life text (email, chat, news…)
   prod {t,task,checks:[[regex,label]],model,e}     free production with self-check */
(function(){
const R=a=>a[Math.floor(Math.random()*a.length)];
const SH=a=>{a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
const cap=s=>s.charAt(0).toUpperCase()+s.slice(1);
const VT=`be,was,been,being,is|have,had,had,having,has|buy,bought,bought,buying,buys|write,wrote,written,writing,writes|read,read,read,reading,reads|watch,watched,watched,watching,watches|lose,lost,lost,losing,loses|finish,finished,finished,finishing,finishes|clean,cleaned,cleaned,cleaning,cleans|cook,cooked,cooked,cooking,cooks|paint,painted,painted,painting,paints|send,sent,sent,sending,sends|fix,fixed,fixed,fixing,fixes|visit,visited,visited,visiting,visits|meet,met,met,meeting,meets|book,booked,booked,booking,books|sell,sold,sold,selling,sells|make,made,made,making,makes|take,took,taken,taking,takes|win,won,won,winning,wins|break,broke,broken,breaking,breaks|eat,ate,eaten,eating,eats|see,saw,seen,seeing,sees|pass,passed,passed,passing,passes|organise,organised,organised,organising,organises|download,downloaded,downloaded,downloading,downloads|build,built,built,building,builds|arrest,arrested,arrested,arresting,arrests|discover,discovered,discovered,discovering,discovers|approve,approved,approved,approving,approves|destroy,destroyed,destroyed,destroying,destroys|plant,planted,planted,planting,plants|steal,stole,stolen,stealing,steals|mark,marked,marked,marking,marks|cancel,cancelled,cancelled,cancelling,cancels|study,studied,studied,studying,studies|get,got,got,getting,gets|catch,caught,caught,catching,catches|save,saved,saved,saving,saves|train,trained,trained,training,trains|leave,left,left,leaving,leaves|arrive,arrived,arrived,arriving,arrives|revise,revised,revised,revising,revises|pay,paid,paid,paying,pays|listen,listened,listened,listening,listens|understand,understood,understood,understanding,understands|practise,practised,practised,practising,practises|play,played,played,playing,plays|live,lived,lived,living,lives|go,went,gone,going,goes|speak,spoke,spoken,speaking,speaks|learn,learnt,learnt,learning,learns|know,knew,known,knowing,knows|spend,spent,spent,spending,spends|stay,stayed,stayed,staying,stays|forget,forgot,forgotten,forgetting,forgets|do,did,done,doing,does|help,helped,helped,helping,helps|check,checked,checked,checking,checks|call,called,called,calling,calls|start,started,started,starting,starts|tidy,tidied,tidied,tidying,tidies|use,used,used,using,uses|travel,travelled,travelled,travelling,travels|invite,invited,invited,inviting,invites|record,recorded,recorded,recording,records|design,designed,designed,designing,designs|translate,translated,translated,translating,translates|publish,published,published,publishing,publishes|repair,repaired,repaired,repairing,repairs|test,tested,tested,testing,tests|cut,cut,cut,cutting,cuts|renew,renewed,renewed,renewing,renews|service,serviced,serviced,servicing,services|shorten,shortened,shortened,shortening,shortens|clean,cleaned,cleaned,cleaning,cleans|deliver,delivered,delivered,delivering,delivers|install,installed,installed,installing,installs|wash,washed,washed,washing,washes|tell,told,told,telling,tells|stop,stopped,stopped,stopping,stops|close,closed,closed,closing,closes|open,opened,opened,opening,opens|choose,chose,chosen,choosing,chooses|bring,brought,brought,bringing,brings|forgive,forgave,forgiven,forgiving,forgives|give,gave,given,giving,gives|join,joined,joined,joining,joins|move,moved,moved,moving,moves|wear,wore,worn,wearing,wears|drink,drank,drunk,drinking,drinks|drive,drove,driven,driving,drives|think,thought,thought,thinking,thinks|say,said,said,saying,says|believe,believed,believed,believing,believes`;
const V={};VT.split('|').forEach(l=>{const[b,p,pp,ing,s]=l.split(',');V[b]={b,p,pp,ing,s}});
const f=(b,k)=>(V[b]||{b,p:b+'ed',pp:b+'ed',ing:b+'ing',s:b+'s'})[k];
const PEOPLE=[['Lucía','she','her','her','herself'],['Marc','he','him','his','himself'],['Aisha','she','her','her','herself'],['Pablo','he','him','his','himself'],['Emma','she','her','her','herself'],['Hugo','he','him','his','himself'],['Nora','she','her','her','herself'],['Leo','he','him','his','himself'],['Sara','she','her','her','herself'],['Adam','he','him','his','himself'],['Iris','she','her','her','herself'],['Dani','he','him','his','himself'],['Carla','she','her','her','herself'],['Jordi','he','him','his','himself']];
const who=(not)=>{let x;do{x=R(PEOPLE)}while(not&&x[0]===not.n);return{n:x[0],p:x[1],o:x[2],ps:x[3],r:x[4],P:cap(x[1]),PS:cap(x[3])}};
const sub=(s,S)=>s.replace(/\{ps\}/g,S.ps).replace(/\{p\}/g,S.p).replace(/\{o\}/g,S.o).replace(/\{r\}/g,S.r);
// activities: [verb, object, durative?]
const ACT=[['buy','a new laptop'],['write','an email to the school',1],['read','the whole novel',1],['watch','the documentary',1],['lose','the house keys'],['finish','the history project'],['clean','the kitchen',1],['cook','dinner for everyone',1],['paint','the living room',1],['send','the application form'],['fix','the old bike',1],['visit','the Prado Museum'],['meet','the new neighbours'],['book','the flights'],['sell','the old car'],['make','a video for class',1],['take','the driving test'],['win','the debate competition'],['break','the printer'],['eat','sushi'],['see','the Northern Lights'],['pass','the maths exam'],['organise','the end-of-year party',1],['download','the new app'],['learn','the irregular verbs',1],['record','a podcast',1],['invite','the whole class'],['revise','the vocabulary',1],['translate','the song lyrics',1],['design','a poster for the campaign',1]];
const DUR=ACT.filter(a=>a[2]),ACTI=ACT.filter(a=>!['lose','break'].includes(a[0])),STUDY=[['revise','the vocabulary'],['finish','the history project'],['read','the whole novel'],['learn','the irregular verbs'],['translate','the song lyrics'],['write','the essay']];
function mc(ctx,q,ok,bad,e,extra){const o=[ok];for(const b of bad.concat(extra||[]))if(o.length<4&&b&&!o.includes(b))o.push(b);const s=SH(o);return{t:'mc',ctx,q,o:s,a:s.indexOf(ok),e}}
const tr=(ctx,q,start,key,a,e)=>({t:'tr',ctx,q,s:start||'',k:key||'',a,e});
const prod=(task,checks,model,e)=>({t:'prod',task,checks,model,e});

/* ======================= UNITS ======================= */
const U={};

/* ---------- verb tenses ---------- */
U.tenses={
 mc(){const S=who(),[v,o]=R(ACT),k=R(['past','pp','pastperf','pastcont','futperf','futcont','ppc']);
  const pp=f(v,'pp'),ps=f(v,'p'),ing=f(v,'ing');
  if(k==='past'){const te=R(['yesterday','last weekend','two days ago','in 2023','last summer']);return mc('',`${S.n} ___ ${o} ${te}.`,ps,[`has ${pp}`,`had ${pp}`,`is ${ing}`],[`Past simple: a finished action at a specific past time (“${te}”).`,`Past simple: acción terminada en un momento concreto del pasado (“${te}”).`])}
  if(k==='pp'){const te=R(['this week','three times this year','so far today','this month']);return mc('',`${S.n} ___ ${o} ${te}.`,`has ${pp}`,[ps,`had ${pp}`,`was ${ing}`],[`Present perfect: an unfinished period of time (“${te}”).`,`Present perfect: periodo de tiempo no terminado (“${te}”).`])}
  if(k==='pastperf'){return mc('',`When we arrived, ${S.n} had already ___ ${o}.`,pp,[ps,ing,`been ${ing}`,v,`have ${pp}`],['Past perfect: an action completed before another past action (we arrived).','Past perfect: acción terminada antes de otra acción pasada (we arrived).'])}
  if(k==='pastcont'){const[d,od]=R(DUR);return mc('',`${S.n} ___ ${od} when the lights went out.`,`was ${f(d,'ing')}`,[f(d,'p'),`had ${f(d,'pp')}`,`has been ${f(d,'ing')}`],['Past continuous: an action in progress interrupted by a short past action.','Past continuous: acción en progreso interrumpida por otra acción breve en pasado.'])}
  if(k==='futperf'){const te=R(['By next Friday','By the end of the month','By the time you get here']);return mc('',`${te}, ${S.n} ___ ${o}.`,`will have ${pp}`,[`will ${v}`,`has ${pp}`,`is ${ing}`],[`Future perfect: completed before a future moment (“${te.toLowerCase()}”).`,`Future perfect: terminado antes de un momento futuro (“${te.toLowerCase()}”).`])}
  if(k==='futcont'){const[d,od]=R(DUR);return mc('',`Don't call ${S.o} at eight tonight: ${S.p} ___ ${od} then.`,`will be ${f(d,'ing')}`,[`will have ${f(d,'pp')}`,`has ${f(d,'pp')}`,f(d,'s')],['Future continuous: an action in progress at a specific future time.','Future continuous: acción en progreso en un momento concreto del futuro.'])}
  const[d,od]=R(DUR);return mc(`${S.n} looks exhausted.`,`${S.P} ___ ${od} since nine o'clock this morning.`,`has been ${f(d,'ing')}`,[`is ${f(d,'ing')}`,`was ${f(d,'ing')}`,f(d,'p')],['Present perfect continuous: an activity that started in the past and is still going on (since…).','Present perfect continuous: actividad que empezó en el pasado y continúa (since…).'])},
 tr(){const S=who(),[v,o]=R(ACT),k=R([0,1,2]);
  if(k===0)return tr('',`It's the first time ${S.n} has ${f(v,'pp')} ${o}.`,`${S.n} has never`,'',[`${S.n} has never ${f(v,'pp')} ${o} before`],['It\'s the first time + present perfect → never… before.','It\'s the first time + present perfect → never… before.']);
  if(k===1){const y=R(['2021','2022','2023','March']);return tr('',`The last time ${S.n} ${f(v,'p')} ${o} was in ${y}.`,`${S.n} hasn't`,'',[`${S.n} hasn't ${f(v,'pp')} ${o} since ${y}`,`${S.n} has not ${f(v,'pp')} ${o} since ${y}`],['The last time… was in → present perfect negative + since.','The last time… was in → present perfect negativo + since.'])}
  const[d,od]=R(DUR),h=R(['two','three','four']);return tr('',`${S.n} started ${f(d,'ing')} ${od} ${h} hours ago and ${S.p} is still doing it.`,'','for',[`${S.n} has been ${f(d,'ing')} ${od} for ${h} hours`],['Started… ago and still doing it → present perfect continuous + for.','Empezó hace… y sigue → present perfect continuous + for.'])},
 frame:{frame:'email',title:'Subject: News from my exchange in Dublin',intro:'Hi! Sorry I haven\'t written for ages. Here is some news about the people in my group:',outro:'Write back soon and tell me about Valencia!'},
 prod:()=>prod('Write an email to a friend (3–4 sentences) about your week. Use the present perfect AND the past simple at least once each.',[[/\b(have|has|'ve|'s)\s+(just |already |never |recently )?\w+(ed|en|t|wn|ne|ght|ck|un|ung|ade|ut)\b/i,'present perfect (have/has + past participle)'],[/\b(yesterday|last|ago|on (monday|tuesday|wednesday|thursday|friday|saturday|sunday))\b/i,'a past time expression for the past simple (yesterday, last…, …ago)']],"This week has been crazy! I've finished my history project and I've started revising for the PAU. Yesterday I went to the cinema with Ana and we watched a great film.",['Mix tenses with clear time expressions.','Combina tiempos con expresiones temporales claras.'])
};

/* ---------- modal verbs ---------- */
const SIGNS=[['museum','No photos, please','take photos'],['library','Silence in the reading room','talk loudly'],['petrol station','No smoking','smoke'],['swimming pool','No diving','dive into the pool'],['exam room','Phones must be switched off','use your phone'],['hospital','No visitors after 9 pm','visit patients after 9 pm']];
const OPTIONAL=[['the school uniform is optional','wear a uniform'],['the trip to London is optional','go on the trip'],['homework at weekends is optional','do homework at weekends'],['Saturday training is optional','go to training on Saturdays'],['the extra exam is optional','take the extra exam']];
const PROBLEMS=[['always feels tired','go to bed earlier'],['has a terrible toothache','see a dentist'],['spends five hours a day on social media','turn off the notifications'],['is really nervous about the PAU','do some mock exams'],['wants to improve {ps} English','watch series in English'],['has had an argument with {ps} best friend','talk to {o} calmly'],['can\'t concentrate when {p} studies','leave {ps} phone in another room']];
const SURE=[['has been studying for twelve hours','be exhausted','must'],['has just won a scholarship','be delighted','must'],['has just eaten a huge pizza','be hungry','can\'t'],['is wearing a coat and a scarf in July','be ill','must'],['was in Paris all week','be the person you saw in Valencia','can\'t'],['knows every word of the song','be a big fan','must'],['has never been abroad','speak fluent Japanese','can\'t']];
U.modals={
 mc(){const S=who(),k=R(['sign','opt','sure','might','advice','better','able']);
  if(k==='sign'){const[pl,txt,act]=R(SIGNS);return mc(`The sign at the ${pl} says: “${txt}”.`,`You ___ ${act} here.`,"mustn't",["don't have to","needn't","should"],['Prohibition: mustn\'t (it is not allowed).','Prohibición: mustn\'t (no está permitido).'])}
  if(k==='opt'){const[c,act]=R(OPTIONAL);return mc(`At ${S.n}'s school, ${c}.`,`${S.n} ___ ${act}.`,"doesn't have to",["mustn't","can't","shouldn't"],['No obligation: don\'t/doesn\'t have to (it is not necessary).','Ausencia de obligación: don\'t/doesn\'t have to (no es necesario).'])}
  if(k==='sure'){const[ev,c,m]=R(SURE);return mc(`${S.n} ${ev}.`,`${S.P} ___ ${c}.`,m,m==='must'?["can't","mustn't","needn't"]:["mustn't","must","doesn't have to"],m==='must'?['Positive deduction (you are sure it is true): must.','Deducción positiva (estás seguro de que es verdad): must.']:['Negative deduction (you are sure it is impossible): can\'t.','Deducción negativa (estás seguro de que es imposible): can\'t.'])}
  if(k==='might'){const x=R([['Take an umbrella.','It ___ rain later.'],[`${S.n} isn't sure about tonight.`,`${S.P} ___ go to the concert, or ${S.p} ___ stay at home.`.replace(/___ stay/,'might stay')],[`The forecast isn't clear.`,'It ___ snow in the mountains this weekend.']]);return mc(x[0],x[1],'might',['must','has to','can\'t'],['Possibility: might / may / could.','Posibilidad: might / may / could.'])}
  if(k==='advice'){const[pr,ad]=R(PROBLEMS);return mc(`Your friend ${S.n} ${sub(pr,S)}.`,`You tell ${S.o}: “You ___ ${sub(ad,S)}.”`,'should',["mustn't","needn't","can't"],['Advice: should / ought to.','Consejo: should / ought to.'])}
  if(k==='better'){const x=R(['It\'s already late.','The exam starts in ten minutes.','It\'s getting dark.']);return mc(x,`You ___ hurry or you'll be late.`,'had better',['would','should to','must to'],['Had better + bare infinitive: strong advice with a warning.','Had better + infinitivo sin to: consejo fuerte con advertencia.'])}
  return mc(`${S.n} is taking driving lessons.`,`Next year ${S.p} will ___ drive.`,'be able to',['can','could','may'],['After will we need be able to (can has no future form).','Tras will necesitamos be able to (can no tiene futuro).'])},
 tr(){const S=who(),k=R([0,1,2,3,4]);
  if(k===0){const[c,act]=R(OPTIONAL);return tr('',`It isn't necessary for ${S.n} to ${act}.`,'','have',[`${S.n} doesn't have to ${act}`,`${S.n} does not have to ${act}`],['Not necessary → don\'t/doesn\'t have to.','No es necesario → don\'t/doesn\'t have to.'])}
  if(k===1){const[ev,c,m]=R(SURE.filter(x=>x[2]==='must'));return tr('',`I'm sure ${S.n} is ${c.replace(/^be /,'')}.`,`${S.n} must`,'',[`${S.n} must ${c}`],['I\'m sure → must (deduction).','Estoy seguro → must (deducción).'])}
  if(k===2){const[ev,c,m]=R(SURE.filter(x=>x[2]!=='must'));return tr('',`It's impossible that ${S.n} is ${c.replace(/^be /,'')}.`,`${S.n} can't`,'',[`${S.n} can't ${c}`,`${S.n} cannot ${c}`],['It\'s impossible → can\'t (deduction).','Es imposible → can\'t (deducción).'])}
  if(k===3){const[pr,ad]=R(PROBLEMS);return tr('',`It's a good idea for ${S.n} to ${sub(ad,S)}.`,'','should',[`${S.n} should ${sub(ad,S)}`],['A good idea → should (advice).','Es buena idea → should (consejo).'])}
  const[pl,txt,act]=R(SIGNS);return tr('',`It is forbidden to ${act} in the ${pl}.`,'You','',[`You mustn't ${act} in the ${pl}`,`You must not ${act} in the ${pl}`,`You can't ${act} in the ${pl}`],['Forbidden → mustn\'t.','Prohibido → mustn\'t.'])},
 frame:{frame:'chat',title:'Group chat · “Help me, please!”',intro:'Your friends are asking for advice in the class group chat. Complete the replies.',outro:''},
 prod:()=>{const S=who(),[pr,ad]=R(PROBLEMS);return prod(`Your friend ${S.n} ${sub(pr,S)}. Write a short message (2–3 sentences) giving advice. Use should, ought to or had better, and one more modal (must, have to, might…).`,[[/\b(should|ought to|had better|'d better)\b/i,'advice modal (should / ought to / had better)'],[/\b(must|mustn't|have to|has to|don't have to|might|may|could|can't)\b/i,'a second modal verb']],`You should ${sub(ad,S)}. You might feel better in a few days, but you mustn't give up!`,['Advice + another modal.','Consejo + otro modal.'])}
};

/* ---------- modal perfects ---------- */
const MP=[
 ['The streets are wet this morning.','It ___ rained during the night.','must have',['can\'t have','needn\'t have','should have'],['Certain deduction about the past: must have + past participle.','Deducción segura sobre el pasado: must have + participio.']],
 ['{n}\'s eyes are red and puffy.','{P} ___ been crying.','must have',['can\'t have','needn\'t have','shouldn\'t have'],['Certain deduction about the past: must have.','Deducción segura sobre el pasado: must have.']],
 ['{n} got a 10 in the exam.','{P} ___ studied a lot.','must have',['can\'t have','needn\'t have','shouldn\'t have'],['Certain deduction about the past: must have.','Deducción segura sobre el pasado: must have.']],
 ['{n} was in Paris all week.','You ___ seen {o} in Valencia on Tuesday.','can\'t have',['must have','should have','needn\'t have'],['Impossible in the past: can\'t / couldn\'t have.','Imposible en el pasado: can\'t / couldn\'t have.']],
 ['{n} isn\'t answering {ps} phone.','{P} ___ left it at home — I\'m not sure.','might have',['must have','needn\'t have','should have'],['Possibility about the past: might / may / could have.','Posibilidad sobre el pasado: might / may / could have.']],
 ['{n} failed the exam because {p} didn\'t study.','{P} ___ studied harder.','should have',['must have','can\'t have','needn\'t have'],['Criticism or regret: should have + past participle.','Crítica o arrepentimiento: should have + participio.']],
 ['{n} feels sick now.','{P} ___ eaten so much chocolate.','shouldn\'t have',['mustn\'t have','can\'t have','needn\'t have'],['It was done but it was a mistake: shouldn\'t have.','Se hizo pero fue un error: shouldn\'t have.']],
 ['{n} cooked for ten people, but only four came.','{P} ___ cooked so much food.','needn\'t have',['mustn\'t have','can\'t have','couldn\'t'],['It was done but it was not necessary: needn\'t have.','Se hizo pero no era necesario: needn\'t have.']],
 ['{n} drove too fast in the rain.','{P} ___ had an accident — luckily {p} didn\'t.','could have',['must have','should have','needn\'t have'],['A possibility that did not happen: could have.','Posibilidad que no llegó a ocurrir: could have.']],
 ['The window is broken and the TV has gone.','A burglar ___ got in through the window.','must have',['can\'t have','needn\'t have','shouldn\'t have'],['Certain deduction about the past: must have.','Deducción segura sobre el pasado: must have.']]];
const MPX=[['I\'m absolutely sure about it:','must have',['can\'t have','needn\'t have','should have'],['Certainty about the past: must have.','Certeza sobre el pasado: must have.']],['That\'s impossible!','can\'t have',['must have','should have','might have'],['Impossibility about the past: can\'t have.','Imposibilidad sobre el pasado: can\'t have.']],['I\'m not sure, but','might have',['must have','can\'t have','needn\'t have'],['Possibility about the past: might / may / could have.','Posibilidad sobre el pasado: might / may / could have.']],['It was a bad idea:','shouldn\'t have',['mustn\'t have','can\'t have','needn\'t have'],['A past mistake: shouldn\'t have.','Un error del pasado: shouldn\'t have.']],['It was the right thing to do, but nobody did it:','should have',['must have','can\'t have','needn\'t have'],['Criticism: should have (it didn\'t happen).','Crítica: should have (no ocurrió).']]];
U['modal-perfects']={
 mc(){if(Math.random()<.5){const S=who(),[v,o]=R(ACT),[c,a,b,e]=R(MPX);return mc(c,`${S.n} ___ ${f(v,'pp')} ${o}.`,a,b,e)}
  const S=who(),[c,q,a,b,e]=R(MP),g=s=>s.replace(/\{n\}/g,S.n).replace(/\{P\}/g,S.P).replace(/\{o\}/g,S.o).replace(/\{ps\}/g,S.ps).replace(/\{p\}/g,S.p);return mc(g(c),g(q),a,b,e)},
 tr(){const S=who(),[v,o]=R(ACT),k=R([0,1,2,3,4]),pp=f(v,'pp'),ps=f(v,'p');
  if(k===0)return tr('',`I'm sure ${S.n} ${ps} ${o}.`,`${S.n} must`,'',[`${S.n} must have ${pp} ${o}`],['I\'m sure + past → must have + past participle.','Estoy seguro + pasado → must have + participio.']);
  if(k===1)return tr('',`It's impossible that ${S.n} ${ps} ${o}.`,`${S.n} can't`,'',[`${S.n} can't have ${pp} ${o}`,`${S.n} cannot have ${pp} ${o}`],['Impossible + past → can\'t have + past participle.','Imposible + pasado → can\'t have + participio.']);
  if(k===2)return tr('',`Perhaps ${S.n} ${ps} ${o}.`,'','might',[`${S.n} might have ${pp} ${o}`],['Perhaps + past → might have + past participle.','Quizás + pasado → might have + participio.']);
  if(k===3)return tr('',`It was a mistake for ${S.n} to ${v} ${o}.`,'',"shouldn't",[`${S.n} shouldn't have ${pp} ${o}`,`${S.n} should not have ${pp} ${o}`],['It was a mistake → shouldn\'t have + past participle.','Fue un error → shouldn\'t have + participio.']);
  return tr('',`It wasn't necessary for ${S.n} to ${v} ${o}, but ${S.p} did.`,'',"needn't",[`${S.n} needn't have ${pp} ${o}`,`${S.n} need not have ${pp} ${o}`],['Done but unnecessary → needn\'t have + past participle.','Hecho pero innecesario → needn\'t have + participio.'])},
 frame:{frame:'notes',title:'Detective notes · The mystery of the school party',intro:'Something strange happened at the end-of-year party. Complete the detective\'s notes.',outro:'Case closed… or is it?'},
 prod:()=>prod('Your phone has disappeared from your desk at school. Write three sentences speculating about what happened. Use must have, might have and can\'t have.',[[/\bmust have\b/i,'must have'],[/\b(might|may|could) have\b/i,'might / may / could have'],[/\b(can't|cannot|couldn't) have\b/i,"can't have"]],"Someone must have taken it during the break. I might have left it in the gym. It can't have been my best friend because she was with me all morning.",['Use modal perfects to speculate about the past.','Usa modales perfectos para especular sobre el pasado.'])
};

/* ---------- passive ---------- */
const PAS=[['the city council','build','a new library',0],['the police','arrest','two suspects',1],['scientists','discover','a new species of frog',0],['a local company','make','these solar panels',1],['the government','approve','the new law',0],['thousands of fans','watch','the final',0],['a famous artist','paint','the mural',0],['the students','organise','the charity concert',0],['the teachers','mark','the exams',1],['an earthquake','destroy','several buildings',1],['volunteers','plant','hundreds of trees',1],['hackers','steal','the passwords',1],['the school','cancel','the trip',0],['an engineer','design','the new bridge',0],['a translator','translate','the novel',0],['the company','deliver','the parcels',1],['a technician','install','the new computers',1]];
const IMP=[['the castle','haunted'],['the singer','very rich'],['the river','polluted'],['the new coach','very strict'],['the old factory','dangerous'],['the restaurant','the best in town']];
U.passive={
 mc(){const[ag,v,o,pl]=R(PAS),k=R(['past','pp','fut','cont','modal']),be=pl?'were':'was',ha=pl?'have':'has',is=pl?'are':'is',O=cap(o),pp=f(v,'pp');
  if(k==='past')return mc('Breaking news',`${O} ___ by ${ag} last year.`,`${be} ${pp}`,[`${ha} ${pp}`,f(v,'p'),`${be} ${f(v,'ing')}`],['Past simple passive: was/were + past participle.','Pasiva en past simple: was/were + participio.']);
  if(k==='pp')return mc('Breaking news',`${O} ${ha} just ___ by ${ag}.`,`been ${pp}`,[pp,`being ${pp}`,`be ${pp}`],['Present perfect passive: has/have been + past participle.','Pasiva en present perfect: has/have been + participio.']);
  if(k==='fut')return mc('Coming soon',`${O} ___ by ${ag} next month.`,`will be ${pp}`,[`will ${v}`,`will been ${pp}`,`is ${pp}`],['Future passive: will be + past participle.','Pasiva en futuro: will be + participio.']);
  if(k==='cont')return mc('Right now',`${O} ___ by ${ag} at the moment.`,`${is} being ${pp}`,[`${is} ${f(v,'ing')}`,`${is} been ${pp}`,`${be} ${pp}`],['Present continuous passive: am/is/are being + past participle.','Pasiva en presente continuo: am/is/are being + participio.']);
  return mc('Official notice',`${O} must ___ before Friday.`,`be ${pp}`,[pp,`been ${pp}`,`being ${pp}`],['Modal passive: modal + be + past participle.','Pasiva con modal: modal + be + participio.'])},
 tr(){const k=R([0,0,0,1,1,1,2,3]);
  if(k<2){const[ag,v,o,pl]=R(PAS),O=cap(o),pp=f(v,'pp');
   if(k===0)return tr('',`${cap(ag)} ${f(v,'p')} ${o} last year.`,O,'',[`${O} ${pl?'were':'was'} ${pp} by ${ag} last year`,`${O} ${pl?'were':'was'} ${pp} last year`,`${O} ${pl?'were':'was'} ${pp} last year by ${ag}`],['Active past simple → was/were + past participle (by + agent).','Activa en pasado → was/were + participio (by + agente).']);
   return tr('',`${cap(ag)} ${ag.match(/s$|police|teachers|fans|students|volunteers|hackers/)?'have':'has'} just ${pp} ${o}.`,O,'',[`${O} ${pl?'have':'has'} just been ${pp} by ${ag}`,`${O} ${pl?'have':'has'} just been ${pp}`],['Present perfect active → has/have been + past participle.','Present perfect activa → has/have been + participio.'])}
  const[x,c]=R(IMP),vb=R(['say','believe','think']),vp=f(vb,'pp');
  if(k===2)return tr('',`People ${vb} that ${x} is ${c}.`,cap(x),'',[`${cap(x)} is ${vp} to be ${c}`],['Impersonal passive: subject + is said/believed/thought + to be.','Pasiva impersonal: sujeto + is said/believed/thought + to be.']);
  return tr('',`People ${vb} that ${x} is ${c}.`,'It','',[`It is ${vp} that ${x} is ${c}`],['Impersonal passive: It is said/believed/thought that…','Pasiva impersonal: It is said/believed/thought that…'])},
 frame:{frame:'news',title:'VALENCIA DAILY · Local news in brief',intro:'Complete the news stories with the correct passive form.',outro:'More news on page 4.'},
 prod:()=>prod('Write three short headlines-style sentences for your school newspaper about things that happened this term. Use the passive (was/were + past participle, has been…).',[[/\b(was|were|is|are|has been|have been|will be|being)\s+(\w+ly\s+)?\w+(ed|en|t|wn|ne|ght|ld|ung|ade|ut|ld)\b/i,'a passive form (be + past participle)'],[/\bby\b/i,'an agent with by (when it is important)']],'A new science lab was opened by the mayor in October. Our football team has been invited to the national finals. Over 500 trees were planted by students.',['Passive: focus on the action, not who did it.','Pasiva: el foco está en la acción, no en quién la hace.'])
};

/* ---------- causative ---------- */
const SERV=[['hair','cut','hairdresser\'s'],['car','repair','garage'],['eyes','test','optician\'s'],['teeth','check','dentist\'s'],['laptop','fix','repair shop'],['bike','service','bike shop'],['jacket','clean','dry cleaner\'s'],['passport','renew','police station'],['photo','take','photographer\'s'],['trousers','shorten','tailor\'s']];
const BAD=[['phone','stolen','on the bus'],['bag','stolen','at the airport'],['flight','cancelled','because of the storm'],['car','broken into','last night'],['bike','stolen','outside the gym']];
U.causative={
 mc(){const S=who(),k=R(['past','fut','neg','haveSb','getSb']);
  if(k==='past'){const[o,v,pl]=R(SERV);return mc(`${S.n} didn't ${v} ${S.ps} ${o} ${S.r}.`,`${S.P} ___ at the ${pl} last week.`,`had ${S.ps} ${o} ${f(v,'pp')}`,[`had ${f(v,'pp')} ${S.ps} ${o}`,`${f(v,'p')} ${S.ps} ${o}`,`had ${S.ps} ${o} ${f(v,'ing')}`],['Causative: have + object + past participle (someone else does it).','Causativa: have + objeto + participio (otra persona lo hace).'])}
  if(k==='fut'){const[o,v,pl]=R(SERV);return mc(`${S.n} has booked an appointment at the ${pl}.`,`${S.P} is going to ___ tomorrow.`,`have ${S.ps} ${o} ${f(v,'pp')}`,[`have ${f(v,'pp')} ${S.ps} ${o}`,`${v} ${S.ps} ${o}`,`having ${S.ps} ${o} ${f(v,'pp')}`],['The verb have changes tense; the object and past participle stay the same.','El verbo have cambia de tiempo; objeto y participio no cambian.'])}
  if(k==='neg'){const[o,v,pl]=R(BAD);return mc('A bad day',`${S.n} ___ ${S.ps} ${o} ${v} ${pl}.`,'had',['has','made','got to'],['Causative for negative experiences: have + object + past participle.','Causativa para experiencias negativas: have + objeto + participio.'])}
  if(k==='haveSb'){const[o,v,pl]=R(SERV);return mc(`${S.n} went to the ${pl}.`,`${S.P} had the expert ___ ${S.ps} ${o}.`,v,[`to ${v}`,f(v,'pp'),f(v,'ing'),`to ${f(v,'ing')}`,f(v,'s')],['have + person + bare infinitive.','have + persona + infinitivo sin to.'])}
  const[v,o]=R(ACTI);return mc(`${S.n} was very busy.`,`${S.P} got ${S.ps} brother ___ ${o} for ${S.o}.`,`to ${v}`,[v,f(v,'ing'),f(v,'pp'),`to ${f(v,'ing')}`,f(v,'s')],['get + person + to + infinitive.','get + persona + to + infinitivo.'])},
 tr(){const S=who(),[o,v,pl]=R(SERV),k=R([0,1,2]),pp=f(v,'pp');
  if(k===0)return tr('',`A professional ${f(v,'p')} ${S.n}'s ${o} yesterday.`,`${S.n} had`,'',[`${S.n} had ${S.ps} ${o} ${pp} yesterday`],['Causative in the past: had + object + past participle.','Causativa en pasado: had + objeto + participio.']);
  if(k===1)return tr('',`Someone is going to ${v} ${S.n}'s ${o} tomorrow.`,`${S.n} is going to`,'',[`${S.n} is going to have ${S.ps} ${o} ${pp} tomorrow`,`${S.n} is going to get ${S.ps} ${o} ${pp} tomorrow`],['Causative with going to: is going to have + object + past participle.','Causativa con going to: is going to have + objeto + participio.']);
  return tr('',`A professional has just ${pp} ${S.n}'s ${o}.`,'','had',[`${S.n} has just had ${S.ps} ${o} ${pp}`],['Present perfect causative: has had + object + past participle.','Causativa en present perfect: has had + objeto + participio.'])},
 frame:{frame:'chat',title:'Chat · “What a week!”',intro:'Your friends are telling you about their week. Complete their messages.',outro:''},
 prod:()=>prod('Write three sentences about things you have done for you by other people (hair, eyes, phone, bike…). Use have/get + object + past participle in different tenses.',[[/\b(had|have|has|having|get|got|getting)\s+(my|his|her|their|our|the)\s+\w+\s+\w+(ed|en|t|cut|done)\b/i,'have/get + object + past participle'],[/\b(going to|will|next|tomorrow|last|yesterday|just)\b/i,'a time reference (last week, tomorrow, just…)']],'I had my hair cut last Saturday. I\'m going to have my eyes tested next week. I\'ve just had my bike repaired.',['Causative: the subject does not do the action.','Causativa: el sujeto no hace la acción.'])
};

/* ---------- reported speech ---------- */
const ADJ=['tired','nervous about the exam','really happy','hungry','bored'];
const WH=[['Where do you live?','where I lived'],['What time do you get up?','what time I got up'],['Why are you late?','why I was late'],['How long have you studied English?','how long I had studied English'],['When will you finish the project?','when I would finish the project'],['What are you doing?','what I was doing']];
U.reported={
 mc(){const S=who(),[v,o]=R(ACTI),k=R(['be','will','pp','past','wh','yn','cmd','sug','adv','deny']);
  if(k==='be'){const a=R(ADJ);return mc(`“I am ${a},” ${S.n} said.`,`${S.n} said that ${S.p} ___ ${a}.`,'was',['is','has been','were'],['Backshift: present simple → past simple.','Backshift: present simple → past simple.'])}
  if(k==='will')return mc(`“I will ${v} ${o} tomorrow,” ${S.n} said.`,`${S.n} said that ${S.p} ___ ${o} the next day.`,`would ${v}`,[`will ${v}`,`would have ${f(v,'pp')}`,f(v,'p')],['will → would; tomorrow → the next day.','will → would; tomorrow → the next day.']);
  if(k==='pp')return mc(`“I have ${f(v,'pp')} ${o},” ${S.n} told me.`,`${S.n} told me that ${S.p} ___ ${o}.`,`had ${f(v,'pp')}`,[`has ${f(v,'pp')}`,f(v,'p'),`have ${f(v,'pp')}`],['Present perfect → past perfect.','Present perfect → past perfect.']);
  if(k==='past')return mc(`“I ${f(v,'p')} ${o} yesterday,” ${S.n} said.`,`${S.n} said that ${S.p} had ${f(v,'pp')} ${o} ___.`,'the day before',['yesterday','tomorrow','the next day'],['yesterday → the day before / the previous day.','yesterday → the day before / the previous day.']);
  if(k==='wh'){const[q,r]=R(WH);return mc(`“${q}” ${S.n} asked me.`,`${S.n} asked me ___.`,r,[q.replace('?','').replace(/^(\w+) (do|are|have|will) you/,(m,w,a)=>w.toLowerCase()+' '+(a==='do'?'did':a==='are'?'was':a==='have'?'had':'would')+' I'),q.replace('?','').toLowerCase(),r.replace(/ I /,' did I ')],['Reported questions: statement word order (subject + verb) and backshift.','Preguntas indirectas: orden de oración afirmativa (sujeto + verbo) y backshift.'])}
  if(k==='yn')return mc(`“Have you ever ${f(v,'pp')} ${o}?” ${S.n} asked me.`,`${S.n} asked me ___ ever ${f(v,'pp')} ${o}.`,'if I had',['had I','if I have','that I had'],['Yes/no questions: if / whether + statement order.','Preguntas de sí/no: if / whether + orden afirmativo.']);
  if(k==='cmd')return mc(`“Don't ${v} ${o}!” ${S.n} told me.`,`${S.n} told me ___ ${o}.`,`not to ${v}`,[`don't ${v}`,`to not ${f(v,'ing')}`,`not ${f(v,'ing')}`],['Negative orders: tell + person + not to + infinitive.','Órdenes negativas: tell + persona + not to + infinitivo.']);
  if(k==='sug')return mc(`“Let's ${v} ${o},” ${S.n} said.`,`${S.n} suggested ___ ${o}.`,f(v,'ing'),[`to ${v}`,`us to ${v}`,v],['suggest + -ing (never suggest to).','suggest + -ing (nunca suggest to).']);
  if(k==='adv')return mc(`“You should ${v} ${o},” ${S.n} said to me.`,`${S.n} advised me ___ ${o}.`,`to ${v}`,[f(v,'ing'),v,`that ${v}`],['advise + person + to + infinitive.','advise + persona + to + infinitivo.']);
  return mc(`“I didn't ${v} ${o}!” ${S.n} said.`,`${S.n} denied ___ ${o}.`,f(v,'ing'),[`to ${v}`,`that ${v}`,v],['deny + -ing.','deny + -ing.'])},
 tr(){const S=who(),[v,o]=R(ACTI),k=R([0,1,2,3,4]);
  if(k===0){const a=R(ADJ);return tr('',`“I am ${a},” ${S.n} said.`,`${S.n} said`,'',[`${S.n} said that ${S.p} was ${a}`,`${S.n} said ${S.p} was ${a}`],['Backshift: am → was; I → he/she.','Backshift: am → was; I → he/she.'])}
  if(k===1)return tr('',`“I will ${v} ${o} tomorrow,” ${S.n} said.`,`${S.n} said`,'',[`${S.n} said that ${S.p} would ${v} ${o} the next day`,`${S.n} said ${S.p} would ${v} ${o} the next day`,`${S.n} said that ${S.p} would ${v} ${o} the following day`,`${S.n} said ${S.p} would ${v} ${o} the following day`],['will → would; tomorrow → the next / following day.','will → would; tomorrow → the next / following day.']);
  if(k===2){const[q,r]=R(WH);return tr('',`“${q}” ${S.n} asked me.`,`${S.n} asked me`,'',[`${S.n} asked me ${r}`],['Reported question: no auxiliary do, statement word order, backshift.','Pregunta indirecta: sin auxiliar do, orden afirmativo, backshift.'])}
  if(k===3)return tr('',`“Let's ${v} ${o},” ${S.n} said.`,`${S.n} suggested`,'',[`${S.n} suggested ${f(v,'ing')} ${o}`,`${S.n} suggested that we should ${v} ${o}`,`${S.n} suggested that we ${v} ${o}`,`${S.n} suggested we should ${v} ${o}`],['suggest + -ing / suggest that we (should) + infinitive.','suggest + -ing / suggest that we (should) + infinitivo.']);
  return tr('',`“You should ${v} ${o},” ${S.n} said to me.`,`${S.n} advised`,'',[`${S.n} advised me to ${v} ${o}`],['advise + person + to + infinitive.','advise + persona + to + infinitivo.'])},
 frame:{frame:'chat',title:'Chat · You missed the class! 😱',intro:'Your classmate is telling you what everybody said in class today.',outro:'See you tomorrow!'},
 prod:()=>prod('Report three things people said to you yesterday (a teacher, a friend, a family member). Use at least two different reporting verbs (said, told, asked, suggested, advised, promised…).',[[/\b(said|told)\b/i,'said / told'],[/\b(asked|suggested|advised|promised|warned|refused|offered|reminded|denied|admitted|apologised|insisted)\b/i,'another reporting verb']],'My teacher told us that the exam would be on Friday. My friend asked me if I wanted to go to the cinema. My mum reminded me to tidy my room.',['Remember the backshift and pronoun changes.','Recuerda el backshift y el cambio de pronombres.'])
};

/* ---------- conditionals ---------- */
const CP=[[['study','harder'],['pass','the exam']],[['get','up earlier'],['catch','the bus']],[['save','more money'],['buy','a car']],[['train','every day'],['win','the race']],[['leave','home earlier'],['arrive','on time']],[['revise','the vocabulary'],['get','a better mark']],[['book','the tickets in advance'],['pay','less']],[['listen','to the teacher'],['understand','the exercise']],[['practise','more'],['play','better']],[['speak','Japanese'],['understand','the film']],[['live','near the beach'],['go','surfing every day']],[['have','more free time'],['learn','to play the guitar']]];
U.conditionals={
 mc(){const S=who(),[[a,ar],[b,br]]=R(CP),k=R(['first','second','third','unless','incase']);
  if(k==='first')return mc(`${S.n} is planning the week.`,`If ${S.n} ${f(a,'s')} ${ar}, ${S.p} ___ ${br}.`,`will ${b}`,[`would ${b}`,`would have ${f(b,'pp')}`,f(b,'s')],['First conditional: If + present, will + infinitive (a real possibility).','Primera condicional: If + presente, will + infinitivo (posibilidad real).']);
  if(k==='second')return mc(`${S.n} doesn't ${a} ${ar}.`,`If ${S.n} ${f(a,'p')} ${ar}, ${S.p} ___ ${br}.`,`would ${b}`,[`will ${b}`,`would have ${f(b,'pp')}`,`had ${f(b,'pp')}`],['Second conditional: If + past simple, would + infinitive (imaginary present).','Segunda condicional: If + past simple, would + infinitivo (presente imaginario).']);
  if(k==='third')return mc(`${S.n} didn't ${a} ${ar}, so ${S.p} didn't ${b} ${br}.`,`If ${S.n} had ${f(a,'pp')} ${ar}, ${S.p} ___ ${br}.`,`would have ${f(b,'pp')}`,[`would ${b}`,`will ${b}`,`had ${f(b,'pp')}`],['Third conditional: If + past perfect, would have + past participle (imaginary past).','Tercera condicional: If + past perfect, would have + participio (pasado imaginario).']);
  if(k==='unless')return mc('A warning',`${S.n} won't ${b} ${br} ___ ${S.p} ${f(a,'s')} ${ar}.`,'unless',['if','in case','whereas'],['unless = if… not (the verb after unless is affirmative).','unless = if… not (el verbo tras unless va en afirmativa).']);
  return mc(`${S.n} is going on a trip.`,`${S.P} is taking an umbrella ___ it rains.`,'in case',['unless','as long as','otherwise'],['in case = as a precaution (por si acaso).','in case = por si acaso.'])},
 tr(){const S=who(),[[a,ar],[b,br]]=R(CP),k=R([0,1,2]);
  if(k===0)return tr('',`${S.n} didn't ${a} ${ar}, so ${S.p} didn't ${b} ${br}.`,`If ${S.n} had`,'',[`If ${S.n} had ${f(a,'pp')} ${ar}, ${S.p} would have ${f(b,'pp')} ${br}`,`If ${S.n} had ${f(a,'pp')} ${ar}, ${S.p}'d have ${f(b,'pp')} ${br}`],['Past fact → third conditional (both parts become positive).','Hecho pasado → tercera condicional (las dos partes pasan a afirmativa).']);
  if(k===1)return tr('',`${S.n} doesn't ${a} ${ar}, so ${S.p} can't ${b} ${br}.`,`If ${S.n}`,'',[`If ${S.n} ${f(a,'p')} ${ar}, ${S.p} could ${b} ${br}`,`If ${S.n} ${f(a,'p')} ${ar}, ${S.p} would ${b} ${br}`,`If ${S.n} ${f(a,'p')} ${ar}, ${S.p} would be able to ${b} ${br}`],['Present fact → second conditional: If + past, could/would + infinitive.','Hecho presente → segunda condicional: If + pasado, could/would + infinitivo.']);
  return tr('',`If ${S.n} doesn't ${a} ${ar}, ${S.p} won't ${b} ${br}.`,'','unless',[`Unless ${S.n} ${f(a,'s')} ${ar}, ${S.p} won't ${b} ${br}`,`${S.n} won't ${b} ${br} unless ${S.p} ${f(a,'s')} ${ar}`,`Unless ${S.n} ${f(a,'s')} ${ar}, ${S.p} will not ${b} ${br}`],['If… not → unless + affirmative verb.','If… not → unless + verbo afirmativo.'])},
 frame:{frame:'forum',title:'Forum · “What should I do this summer?”',intro:'Students are giving advice in a forum. Complete their posts.',outro:''},
 prod:()=>prod('What would you do if you won a trip anywhere in the world? And what would you have done differently last year? Write two or three sentences using a second and a third conditional.',[[/\bif\b[^.]*\b(was|were|had|won|could|got|lived|did)\b[^.]*\b(would|'d|could)\b(?! have)|\b(would|'d|could)\b(?! have)[^.]*\bif\b/i,'second conditional (If + past, would + infinitive)'],[/\b(would|could|might|'d)\s+have\s+\w+/i,'third conditional (would have + past participle)']],'If I won a trip, I would go to Japan and visit Kyoto. If I had studied more last year, I would have got better marks.',['Second = imaginary present; third = imaginary past.','Segunda = presente imaginario; tercera = pasado imaginario.'])
};

/* ---------- wishes ---------- */
const STATE=[['have','a dog'],['live','by the sea'],['speak','German'],['know','the answer'],['have','more free time'],['understand','physics']];
const REG=[['eat','so much chocolate'],['spend','all {ps} money on clothes'],['buy','that expensive jacket'],['stay','up so late'],['forget','{ps} best friend\'s birthday'],['tell','everybody the secret'],['sell','{ps} old guitar']];
const ANNOY=[['{ps} brother always borrows {ps} clothes','{ps} brother','stop','borrowing {ps} clothes'],['the neighbours play loud music every night','the neighbours','stop','playing loud music'],['{ps} friends are always late','{ps} friends','arrive','on time'],['{ps} sister never helps at home','{ps} sister','help','at home'],['{ps} classmates always talk during the film','{ps} classmates','be','quiet']];
U.wishes={
 mc(){const S=who(),k=R(['present','past','would','time','rather','could']);
  if(k==='present'){const[v,o]=R(STATE);return mc(`${S.n} doesn't ${v} ${o}, and ${S.p}'s sad about it.`,`${S.n} wishes ${S.p} ___ ${o}.`,f(v,'p'),[f(v,'s'),`had ${f(v,'pp')}`,`would ${v}`],['Wish about the present: wish + past simple.','Deseo sobre el presente: wish + past simple.'])}
  if(k==='past'){const[v,o]=R(REG),oo=sub(o,S);return mc(`${S.n} ${f(v,'p')} ${oo} and now ${S.p} regrets it.`,`${S.n} wishes ${S.p} ___ ${oo}.`,`hadn't ${f(v,'pp')}`,[`didn't ${v}`,`wouldn't ${v}`,`hasn't ${f(v,'pp')}`],['Regret about the past: wish + past perfect.','Arrepentimiento sobre el pasado: wish + past perfect.'])}
  if(k==='would'){const[sit,who2,vb,rest]=R(ANNOY);return mc(`${cap(sub(sit,S))}. ${S.n} is fed up.`,`${S.n} wishes ${sub(who2,S)} ___ ${sub(rest,S)}.`,`would ${vb}`,[vb==='be'?'are':f(vb,'s'),`will ${vb}`,`had ${f(vb,'pp')}`],['Complaint about other people\'s behaviour: wish + would.','Queja sobre el comportamiento de otros: wish + would.'])}
  if(k==='time'){const[v,o]=R([['go','home'],['start','revising for the PAU'],['tidy','this room'],['leave','for the station']]);return mc('It\'s getting late.',`It's high time we ___ ${o}.`,f(v,'p'),[v,f(v,'ing'),`will ${v}`],['It\'s (high) time + subject + past simple.','It\'s (high) time + sujeto + past simple.'])}
  if(k==='rather'){const[v,o]=R([['tell','anyone about it'],['use','my laptop'],['call','me after ten'],['invite','Marcos']]);return mc(`${S.n} has a request.`,`“I'd rather you ___ ${o}.”`,`didn't ${v}`,[`don't ${v}`,`not to ${v}`,`won't ${v}`],['I\'d rather + another person + past simple.','I\'d rather + otra persona + past simple.'])}
  const[v,o]=R([['play','the piano'],['speak','Chinese'],['drive','a car'],['swim','well']]);return mc(`${S.n} can't ${v} ${o}.`,`${S.n} wishes ${S.p} ___ ${v} ${o}.`,'could',['can','would can','is able'],['Wish about an ability: wish + could.','Deseo sobre una habilidad: wish + could.'])},
 tr(){const S=who(),k=R([0,1,2]);
  if(k===0){const[v,o]=R(REG),oo=sub(o,S);return tr('',`${S.n} regrets ${f(v,'ing')} ${oo}.`,`${S.n} wishes`,'',[`${S.n} wishes ${S.p} hadn't ${f(v,'pp')} ${oo}`,`${S.n} wishes ${S.p} had not ${f(v,'pp')} ${oo}`],['regret + -ing → wish + past perfect.','regret + -ing → wish + past perfect.'])}
  if(k===1){const[v,o]=R(STATE);return tr('',`It's a pity ${S.n} doesn't ${v} ${o}.`,'','wishes',[`${S.n} wishes ${S.p} ${f(v,'p')} ${o}`],['It\'s a pity + present → wish + past simple.','Es una pena + presente → wish + past simple.'])}
  const[v,o]=R(STATE);return tr('',`${S.n} would love to ${v} ${o}, but ${S.p} doesn't.`,'If only','',[`If only ${S.n} ${f(v,'p')} ${o}`,`If only ${S.p} ${f(v,'p')} ${o}`],['If only + past simple = a wish about the present.','If only + past simple = deseo sobre el presente.'])},
 frame:{frame:'diary',title:'Dear diary…',intro:'It\'s been a strange week. Complete the diary entry.',outro:'Tomorrow will be better!'},
 prod:()=>prod('Write three wishes: one about your present life, one regret about the past, and one complaint about someone else (wish + would).',[[/\bwish\b[^.]*\b(were|was|had|could|lived|knew|spoke|did)\b/i,'wish + past (present wish)'],[/\bwish\b[^.]*\bhad(n't| not)?\s+\w+/i,'wish + past perfect (regret)'],[/\bwish\b[^.]*\bwould\b/i,'wish + would (complaint)']],'I wish I had more free time. I wish I hadn\'t spent so much money last summer. I wish my brother would stop using my headphones.',['Present → past simple; past → past perfect; complaint → would.','Presente → past simple; pasado → past perfect; queja → would.'])
};

/* ---------- relative clauses ---------- */
const RW={who:[['the girl','won the poetry prize'],['the man','lives next door'],['the teacher','helped me with my project'],['the student','organised the charity event'],['the woman','speaks five languages']],
 whose:[['the girl','her','father is a pilot'],['the boy','his','sister is in my class'],['the man','his','dog bit my cousin'],['the artist','her','paintings are in the museum'],['the singer','his','songs are everywhere']],
 where:[['the café','we first met'],['the town','my parents grew up'],['the hotel','we stayed last summer'],['the park','I learnt to ride a bike'],['the school','my mum studied']],
 which:[['the book','is on the bestseller list'],['the film','won three Oscars'],['the laptop','broke last week'],['the song','is number one'],['the app','helps you learn vocabulary']],
 when:[['the day','I passed my driving test'],['the year','we moved to Valencia'],['the summer','I met my best friend'],['the moment','the lights went out']]};
U.relatives={
 mc(){const k=R(['who','whose','where','which','when','nd','whole']);
  if(k==='nd'){const S=who(),rel=R(['uncle','aunt','grandfather','cousin']),c=R(['Rome','London','Berlin','Lisbon']),j=R(['a doctor','an engineer','a journalist','a chef']);return mc('Non-defining clause',`My ${rel}, ___ lives in ${c}, is ${j}.`,'who',['that','which','whose'],['Non-defining relative clause (between commas): never that.','Relativa explicativa (entre comas): nunca that.'])}
  if(k==='whole'){const S=who();return mc('Comment on a whole sentence',`${S.n} didn't reply to my messages, ___ really annoyed me.`,'which',['what','that','who'],['which can refer to the whole previous clause.','which puede referirse a toda la oración anterior.'])}
  const opts={who:['which','whose','where'],whose:['who','who\'s','which'],where:['which','when','who'],which:['who','where','whose'],when:['where','which','who']};
  const x=R(RW[k]),q=k==='whose'?`This is ${x[0]} ___ ${x[2]}.`:`This is ${x[0]} ___ ${x[1]}.`;
  const e={who:['People as subject: who / that.','Personas como sujeto: who / that.'],whose:['Possession: whose + noun.','Posesión: whose + sustantivo.'],where:['Place: where.','Lugar: where.'],which:['Things: which / that.','Cosas: which / that.'],when:['Time: when.','Tiempo: when.']}[k];
  return mc('Combine the ideas',q,k,opts[k],e)},
 tr(){const k=R(['who','whose','where','when']),x=R(RW[k]);
  if(k==='who'){const pr=/girl|woman/.test(x[0])?'She':'He';return tr('',`This is ${x[0]}. ${pr} ${x[1]}.`,`This is ${x[0]}`,'',[`This is ${x[0]} who ${x[1]}`,`This is ${x[0]} that ${x[1]}`],['Join with who / that (person, subject).','Une con who / that (persona, sujeto).'])}
  if(k==='whose')return tr('',`This is ${x[0]}. ${cap(x[1])} ${x[2]}.`,`This is ${x[0]}`,'',[`This is ${x[0]} whose ${x[2]}`],['his/her + noun → whose + noun.','his/her + sustantivo → whose + sustantivo.']);
  if(k==='where')return tr('',`This is ${x[0]}. ${cap(x[1])} there.`,`This is ${x[0]}`,'',[`This is ${x[0]} where ${x[1]}`,`This is ${x[0]} in which ${x[1]}`],['there → where.','there → where.']);
  return tr('',`I'll never forget ${x[0]}. ${cap(x[1])} then.`,`I'll never forget ${x[0]}`,'',[`I'll never forget ${x[0]} when ${x[1]}`,`I'll never forget ${x[0]} that ${x[1]}`,`I'll never forget ${x[0]} ${x[1]}`],['then (time) → when.','then (tiempo) → when.'])},
 frame:{frame:'blog',title:'Travel blog · My town in 4 sentences',intro:'Complete this post for an international travel blog.',outro:'Come and visit us! 🌞'},
 prod:()=>prod('Describe your town or neighbourhood for a travel blog (3–4 sentences). Use at least three different relative pronouns (who, which, where, whose, when).',[[/\b(who|that)\b/i,'who / that'],[/\bwhere\b/i,'where'],[/\b(which|whose|when)\b/i,'which / whose / when']],'Valencia is a city where you can enjoy the beach all year. The Albufera, which is a natural park, is perfect for sunsets. My neighbour, whose restaurant is famous, makes the best paella. I love the people who live here.',['Defining vs non-defining: commas change the meaning.','Especificativas vs explicativas: las comas cambian el significado.'])
};

/* ---------- gerunds & infinitives ---------- */
const VING=[['enjoys'],['avoids'],['doesn\'t mind'],['can\'t stand'],['has finished'],['keeps'],['is looking forward to'],['is used to'],['is interested in'],['is good at'],['is thinking of'],['spent the afternoon'],['gave up']];
const VTO=[['decided'],['wants'],['refused'],['managed'],['can\'t afford'],['promised'],['hopes'],['agreed'],['would like'],['is planning'],['seems'],['offered']];
const VBARE=[['made me'],['let me'],['had better'],['would rather']];
U.gerunds={
 mc(){const S=who(),[v,o]=R(ACTI),k=R(['ing','ing','to','to','bare','mean']);
  if(k==='ing'){const[x]=R(VING),pr=/ (to|in|at|of)$/.test(x);return mc('',`${S.n} ${x} ___ ${o}.`,f(v,'ing'),[`to ${v}`,v,`to ${f(v,'ing')}`],[pr?`After a preposition (“${x}”) we use -ing.`:`“${x}” is followed by -ing.`,pr?`Tras preposición (“${x}”) usamos -ing.`:`“${x}” va seguido de -ing.`])}
  if(k==='to'){const[x]=R(VTO);return mc('',`${S.n} ${x} ___ ${o}.`,`to ${v}`,[f(v,'ing'),v,`for ${f(v,'ing')}`],[`“${x}” is followed by to + infinitive.`,`“${x}” va seguido de to + infinitivo.`])}
  if(k==='bare'){const[x]=R(VBARE);return mc('',`${S.n} ${x} ___ ${o}.`,v,[`to ${v}`,f(v,'ing'),f(v,'p'),`to ${f(v,'ing')}`,f(v,'s')],[`“${x}” is followed by the bare infinitive (no to).`,`“${x}” va seguido de infinitivo sin to.`])}
  const m=R([['stopped','to buy a coffee on the way to school',['buying a coffee'],'stop + to = stop in order to do something.','stop + to = parar para hacer algo.','to buy'],['stopped','eating meat two years ago',[],'stop + -ing = quit an activity.','stop + -ing = dejar de hacer algo.','eating'],['remembers','meeting the actor when she was a child',[],'remember + -ing = a memory of the past.','remember + -ing = recuerdo del pasado.','meeting'],['must remember','to lock the door when you leave',[],'remember + to = something you have to do.','remember + to = algo que hay que hacer.','to lock'],['tried','to open the window, but it was stuck',[],'try + to = make an effort.','try + to = intentar.','to open'],['regrets','telling his friend the secret',[],'regret + -ing = be sorry about the past.','regret + -ing = arrepentirse.','telling']]);
  const[vb,rest,,en,es,ok]=m,body=rest.replace(/^(to \w+|\w+ing) ?/,''),alt=ok.startsWith('to ')?f(ok.slice(3),'ing'):'to '+Object.keys(V).find(b=>f(b,'ing')===ok);
  return mc('Verbs that change meaning',`${S.n} ${vb} ___ ${body}.`,ok,[alt,ok.startsWith('to ')?ok.slice(3):Object.keys(V).find(b=>f(b,'ing')===ok),ok.startsWith('to ')?'for '+f(ok.slice(3),'ing'):'to '+ok],[en,es])},
 tr(){const S=who(),[v,o]=R(ACTI),k=R([0,1,2,3]);
  if(k===0)return tr('',`“Let's ${v} ${o},” said ${S.n}.`,`${S.n} suggested`,'',[`${S.n} suggested ${f(v,'ing')} ${o}`],['suggest + -ing.','suggest + -ing.']);
  if(k===1)return tr('',`${S.n} really hates ${f(v,'ing')} ${o}.`,'','stand',[`${S.n} can't stand ${f(v,'ing')} ${o}`,`${S.n} cannot stand ${f(v,'ing')} ${o}`],['can\'t stand + -ing.','can\'t stand + -ing.']);
  if(k===2)return tr('',`${S.n} said “No, I won't ${v} ${o}.”`,'','refused',[`${S.n} refused to ${v} ${o}`],['refuse + to + infinitive.','refuse + to + infinitivo.']);
  return tr('',`${S.n} succeeded in ${f(v,'ing')} ${o}.`,'','managed',[`${S.n} managed to ${v} ${o}`],['succeed in + -ing = manage + to + infinitive.','succeed in + -ing = manage + to + infinitivo.'])},
 frame:{frame:'email',title:'Subject: Application – Summer camp monitor',intro:'Dear Ms Smith, I am writing to apply for the job of summer camp monitor. Complete the rest of the email about the candidates in my group.',outro:'I look forward to hearing from you. Yours sincerely,'},
 prod:()=>prod('Write 3–4 sentences about your free time: what you enjoy, what you can\'t stand, what you have decided to do this summer and what you hope to achieve.',[[/\b(enjoy|love|like|hate|mind|stand|avoid|keep|finish)\w*\s+\w+ing\b/i,'verb + -ing'],[/\b(decide|want|hope|plan|would like|refuse|manage|promise|afford|agree)\w*\s+to\s+\w+/i,'verb + to + infinitive']],"I enjoy going to the beach with my friends, but I can't stand waking up early at weekends. This summer I've decided to learn to surf, and I hope to pass my driving test.",['Each verb has its own pattern: learn them in chunks.','Cada verbo tiene su estructura: apréndelos en bloques.'])
};

/* ---------- linkers ---------- */
const CON=[['it was raining','the rain','we went for a walk'],['{n} was very tired','{ps} tiredness','{p} finished the essay'],['the tickets were expensive','the high price of the tickets','the concert was sold out'],['{n} had a bad cold','{ps} bad cold','{p} played in the final'],['the exam was difficult','the difficulty of the exam','most students passed'],['the hotel was old','its age','it was very comfortable']];
const CAU=[['the match was cancelled','the storm','it was stormy'],['the flight was delayed','the fog','it was foggy'],['the school closed early','the heatwave','it was extremely hot'],['{n} couldn\'t sleep','the noise','the neighbours were noisy']];
U.linkers={
 mc(){const S=who(),g=s=>s.replace(/\{n\}/g,S.n).replace(/\{ps\}/g,S.ps).replace(/\{p\}/g,S.p),k=R(['although','despite','however','cause','causeof','purpose','such','whereas']);
  if(k==='although'){const[c,,m]=R(CON);return mc('Contrast',`___ ${g(c)}, ${g(m)}.`,'Although',['Despite','However','Because of'],['Although + clause (subject + verb).','Although + oración (sujeto + verbo).'])}
  if(k==='despite'){const[,n,m]=R(CON);return mc('Contrast',`___ ${g(n)}, ${g(m)}.`,R(['Despite','In spite of']),['Although','Even though','However'],['Despite / In spite of + noun or -ing (never despite of).','Despite / In spite of + sustantivo o -ing (nunca despite of).'])}
  if(k==='however'){const[c,,m]=R(CON);return mc('Contrast',`${cap(g(c))}. ___, ${g(m)}.`,'However',['Although','Despite','Because'],['However links two separate sentences and is followed by a comma.','However une dos oraciones separadas y va seguido de coma.'])}
  if(k==='cause'){const[r,,c]=R(CAU);return mc('Cause',`${cap(g(r))} ___ ${c}.`,'because',['because of','despite','so'],['because + clause.','because + oración.'])}
  if(k==='causeof'){const[r,n]=R(CAU);return mc('Cause',`${cap(g(r))} ___ ${n}.`,R(['because of','due to']),['because','although','so that'],['because of / due to + noun.','because of / due to + sustantivo.'])}
  if(k==='purpose'){const[v,o]=R(STUDY);return mc('Purpose',`${S.n} went to the library early so as ___ ${o} in peace.`.replace(`___ ${o}`,`___ ${v} ${o}`),'to',['for','that','not'],['so as to / in order to + infinitive (purpose).','so as to / in order to + infinitivo (finalidad).'])}
  if(k==='such'){const x=R([['a good film','we watched it twice'],['an interesting book','I finished it in one day'],['a long journey','we were exhausted'],['nice weather','we spent the day outside']]);return mc('Result',`It was ___ ${x[0]} that ${x[1]}.`,'such',['so','too','very'],['such + (a) + adjective + noun + that.','such + (a) + adjetivo + sustantivo + that.'])}
  return mc('Contrast between two ideas',`${S.n} loves maths, ___ ${S.ps} brother hates it.`,'whereas',['despite','however','because'],['whereas / while: contrast between two facts in the same sentence.','whereas / while: contraste entre dos hechos en la misma oración.'])},
 tr(){const S=who(),g=s=>s.replace(/\{n\}/g,S.n).replace(/\{ps\}/g,S.ps).replace(/\{p\}/g,S.p),[c,n,m]=R(CON),k=R([0,1,2]);
  if(k===0)return tr('',`Although ${g(c)}, ${g(m)}.`,'Despite','',[`Despite ${g(n)}, ${g(m)}`,`Despite the fact that ${g(c)}, ${g(m)}`],['Although + clause → Despite + noun (or the fact that).','Although + oración → Despite + sustantivo (o the fact that).']);
  if(k===1)return tr('',`${cap(g(c))}, but ${g(m)}.`,'In spite of','',[`In spite of ${g(n)}, ${g(m)}`,`In spite of the fact that ${g(c)}, ${g(m)}`],['but → In spite of + noun.','but → In spite of + sustantivo.']);
  return tr('',`${cap(g(c))}. Nevertheless, ${g(m)}.`,'Even though','',[`Even though ${g(c)}, ${g(m)}`],['Nevertheless → Even though + clause.','Nevertheless → Even though + oración.'])},
 frame:{frame:'essay',title:'Opinion essay · Should mobile phones be banned in schools?',intro:'Complete the body paragraph with the best linkers.',outro:'To sum up, the debate is far from over.'},
 prod:()=>prod('Write an opinion paragraph (4 sentences) about this topic: “Teenagers should have a part-time job.” Use although/despite, however, moreover/furthermore and therefore/as a result.',[[/\b(although|even though|despite|in spite of)\b/i,'although / despite'],[/\b(however|nevertheless|on the other hand)\b/i,'however / nevertheless'],[/\b(moreover|furthermore|in addition|what's more)\b/i,'moreover / furthermore'],[/\b(therefore|as a result|consequently)\b/i,'therefore / as a result']],'Although part-time jobs take time, I believe they are very positive for teenagers. Moreover, they teach responsibility and the value of money. However, school must always be the priority. Therefore, a few hours at weekends is the best option.',['Linkers organise your ideas and raise your writing mark.','Los conectores organizan tus ideas y suben la nota del writing.'])
};

/* ======================= engine API ======================= */
function errFrom(it){const bad=it.o.filter((_,i)=>i!==it.a);const w=R(bad);const wrong=it.q.replace('___',w),right=it.q.replace('___',it.o[it.a]);return{t:'err',ctx:it.ctx,q:wrong,a:[right.replace(/[.”]+$/,'')],e:it.e}}
function textFrom(u){const g=U[u],items=[];let tries=0;while(items.length<4&&tries<40){tries++;const it=g.mc();if(!items.some(x=>x.q===it.q))items.push(it)}return Object.assign({t:'text',items},g.frame)}
function make(u,type){const g=U[u];if(!g)return null;
 const types=['mc','mc','tr','err','text','prod'];const t=type&&type!=='all'?type:R(types);
 if(t==='mc')return g.mc();if(t==='tr')return g.tr();if(t==='err')return errFrom(g.mc());if(t==='text')return textFrom(u);return g.prod()}
window.GEN={units:Object.keys(U),make,has:u=>!!U[u]};
})();
